(() => {
  'use strict';
  const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'), mini=document.getElementById('minimap'),mx=mini.getContext('2d');
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const SAVE_KEY='golden-plains-save-v1';
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)],dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const names=['Amara','Nala','Zuri','Kito','Jengo','Sefu','Imani','Tamu','Asha','Simba','Kali','Mosi','Pendo','Jabari','Amani','Kubwa'];
  const stageDefs=[['Newborn',0],['Young cub',14],['Older cub',60],['Juvenile',180],['Subadult',365],['Young adult',912],['Prime adult',1825],['Mature',3285],['Elderly',4745]];
  const palettes=['#c9a35f','#d0ad70','#bd9656','#d6b77c','#bc9d68'];
  let W=innerWidth,H=innerHeight,dpr=1,lastFrame=performance.now(),toastTimer=0,keys={},soundOn=true,viewPanel='pride',mapOpen=false;
  let world,player,pride=[],animals=[],timeOfDay=6.7,season='Dry season',weather='Clear',gameDay=1,events=[],huntTarget=null,mode='walk',camera={x:0,y:0},toastTimeout,actionCooldown=0,moveAccum=0;
  const mkLion=(name,role,ageDays,sex,personality,coat)=>({id:Math.random().toString(36).slice(2,9),name,role,ageDays,sex,personality,coat:coat||pick(palettes),bond:Math.round(rand(62,95)),health:100,alive:true});
  function fresh(){
    const p={name:'Nala',sex:'Lioness',coat:'#c7a263',mane:'#62462e',eyes:'#ac7640',scar:'none',personality:'Curious',temperament:'Steady',ageDays:1170,stage:'Young adult',x:0,y:0,heading:0,needs:{hunger:72,thirst:81,energy:86,stamina:94,health:100,stress:12,temperature:35},injury:0,meat:0,experience:0,offspring:0,mate:'Kito',pregnancy:null,heat:0,lastBirthDay:-1,alive:true,healthState:'Well',milk:0,cubs:[],mother:'Sanaa',father:'Baraka',genetics:{size:1.04,mane:0.2,coat:'#c7a263'},mode:'Life Simulation',daysAlive:0,scarCount:1};
    const members=[mkLion('Kito','Mate',1430,'Male','Playful · Bold','#c5a16b'),mkLion('Sanaa','Mother',3285,'Lioness','Patient · Watchful','#c9a969'),mkLion('Taji','Sister',1095,'Lioness','Bold · Sociable','#b99864'),mkLion('Mika','Sister',815,'Lioness','Gentle · Curious','#d0ad70'),mkLion('Bora','Coalition',1310,'Male','Restless · Loyal','#bd9656')];
    return {player:p,pride:members,world:{elapsed:0,day:1,time:6.7,season:'Dry season',weather:'Clear',seed:7},animals:initialAnimals(),events:[{day:1,text:'A herd of zebra is grazing beyond the acacias.'}]};
  }
  function initialAnimals(){let out=[]; const species=[['Zebra',7,58],['Wildebeest',8,52],['Gazelle',6,45],['Impala',8,45],['Buffalo',4,50],['Warthog',4,33],['Elephant',3,20],['Giraffe',3,17],['Hyena',5,42],['Leopard',1,22],['Cheetah',2,27],['Wild dog',4,30],['Jackal',3,32],['Vulture',3,26],['Crocodile',2,18]];for(const [kind,count,speed] of species)for(let i=0;i<count;i++)out.push({id:Math.random().toString(36).slice(2),kind,x:rand(-650,650),y:rand(-450,450),heading:rand(0,6.28),speed:rand(speed*.65,speed*1.3),state:pick(['graze','wander','rest']),stateTime:rand(2,12),health:100,hunger:rand(20,65),thirst:rand(15,70),alert:0,group:kind==='Zebra'?'Zebra herd':kind==='Impala'?'Impala herd':kind==='Wildebeest'?'Wildebeest herd':'',size:({Elephant:1.6,Giraffe:1.32,Buffalo:1.2})[kind]||1,alive:true});return out}
  function save(){try{world.savedAt=Date.now();localStorage.setItem(SAVE_KEY,JSON.stringify({player,pride,world:{elapsed:world.elapsed,day:gameDay,time:timeOfDay,season,weather,seed:world.seed},animals,events:events.slice(-12)}));toast('Life saved · your pride will be here when you return.')}catch(e){toast('Could not save this life on this device.')}}
  function load(){try{const d=JSON.parse(localStorage.getItem(SAVE_KEY));if(!d?.player)return false;player=d.player;pride=d.pride||[];world=d.world||{elapsed:0,seed:7};animals=d.animals||initialAnimals();events=d.events||[];gameDay=world.day||1;timeOfDay=world.time??6.7;season=world.season||'Dry season';weather=world.weather||'Clear';return true}catch(e){return false}}
  function setup(){if(!load()){const d=fresh();player=d.player;pride=d.pride;world=d.world;animals=d.animals;events=d.events;gameDay=1;timeOfDay=6.7;season='Dry season';weather='Clear'} player.lastTick=Date.now();updateUI();buildPride();resize();requestAnimationFrame(frame);setInterval(save,30000);}
  function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,1.8);canvas.width=W*dpr;canvas.height=H*dpr;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
  const stageFor=days=>{let s=stageDefs[0][0];for(const [n,d] of stageDefs)if(days>=d)s=n;return s};
  const ageText=d=>d<365?`${Math.floor(d/30)} months`:`${Math.floor(d/365)} years, ${Math.floor((d%365)/30)} months`;
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),3100)}
  function note(text){events.push({day:gameDay,text});if(events.length>30)events.shift();$('#event-text').textContent=text;$('#event-card').style.display='flex'}
  function updateUI(){if(!player)return;player.stage=stageFor(player.ageDays);$('#lion-name').textContent=player.name;$('#identity-stage').textContent=`${player.stage.toUpperCase()} · ${player.sex.toUpperCase()}`;$('#age-label').textContent=ageText(player.ageDays);$('#trait-label').textContent=`${player.personality} · ${player.temperament}`;$('#pride-label').textContent=player.mode==='Free Roam'?'The open plains':'Mara Pride';$('#season-label').textContent=`${season.toUpperCase()} · DAY ${String(gameDay).padStart(2,'0')}`;$('#time-label').textContent=`${String(Math.floor(timeOfDay)).padStart(2,'0')}:${String(Math.floor((timeOfDay%1)*60)).padStart(2,'0')}`;$('#weather-label').textContent=weather.toUpperCase();$('#weather-label').previousElementSibling.textContent=weather==='Rain'?'☂':weather==='Cloudy'?'☁':'☀';
    const n=player.needs;for(const k of ['hunger','thirst','energy','stamina','health','stress']){const v=Math.round(clamp(n[k],0,100));const value=$(`#${k}-value`),bar=$(`#${k}-bar`);if(value)value.textContent=v+'%';if(bar)bar.style.width=v+'%'}
    const risk=n.hunger<22||n.thirst<22||n.health<40;$('.condition-status').innerHTML=`<i></i> ${risk?'AT RISK':player.injury>0?'RECOVERING':'WELL'}`;$('.condition-status').style.color=risk?'#e89c79':'#b9d1a5';$('#injury-tag').textContent=player.injury>0?`INJURED · ${Math.round(player.injury)}%`:'NO INJURY';
    const near=nearestThing();if(near){$('#interact-label').textContent=near.kind==='water'?'Drink at the water':'Approach '+near.label;$('#interact-sub').textContent=near.kind==='prey'?'Hold stalk, then pounce':'Interact with nearby '+near.label.toLowerCase()}else{$('#interact-label').textContent='Explore the plains';$('#interact-sub').textContent='Walk close to an animal or landmark'}
    const loc=player.x>230?'River Bend':player.x< -230?'Elephant Ridge':player.y< -150?'Rocky Den':'Acacia Rise';$('#location-name').textContent=loc;$('#location-note').textContent=loc==='River Bend'?'Fresh water · reeds and riverbank':loc==='Rocky Den'?'Sheltered den · cool shade':loc==='Elephant Ridge'?'Rocky outcrop · herds pass here':'Open grassland · 1.2 km to water';
  }
  function buildPride(){const el=$('#pride-members');el.innerHTML='';const group=[{name:player.name,role:'You · '+player.stage,personality:player.personality,alive:true},...pride.filter(a=>a.alive)];$('#panel-heading').innerHTML=`Mara Pride <span class="count-badge">${group.length}</span>`;for(const l of group){const d=document.createElement('div');d.className='member';d.innerHTML=`<div class="member-avatar">${l.sex==='Male'?'♌':'♧'}</div><div><div class="member-name">${l.name}${l===player?' (you)':''}</div><div class="member-detail">${l.role||ageText(l.ageDays)} · ${l.personality||'Steady'}</div></div><div class="member-state">${l===player?'HERE':l===pride.find(x=>x.name===player.mate)?'MATE':pick(['NEARBY','PATROLLING','RESTING'])}</div>`;el.appendChild(d)}$('#pride-status').textContent=`${group.length} lions · bonds change with time together`}
  function nearestThing(){let nearest=null,dd=Infinity;for(const a of animals){if(!a.alive)continue;const d=dist(player,a);if(d<dd&&d<118){nearest={kind:'prey',label:a.kind,animal:a};dd=d}}const waterDist=Math.abs(player.x-260)+Math.abs(player.y-80);if(waterDist<dd&&waterDist<145)nearest={kind:'water',label:'water',distance:waterDist};return nearest}
  function stageSize(){return ({'Newborn':.18,'Young cub':.29,'Older cub':.45,'Juvenile':.65,'Subadult':.85,'Young adult':1,'Prime adult':1.04,'Mature':1,'Elderly':.88})[player.stage]||1}
  function aiStep(dt){for(const a of animals){if(!a.alive)continue;a.stateTime-=dt;a.hunger=clamp(a.hunger+dt*.11,0,100);a.thirst=clamp(a.thirst+dt*.09,0,100);const d=dist(a,player),danger=d<135&&(a.kind==='Zebra'||a.kind==='Wildebeest'||a.kind==='Gazelle'||a.kind==='Impala'||a.kind==='Buffalo'||a.kind==='Warthog');if(danger){a.alert=Math.max(a.alert,2);a.state='flee';a.heading=Math.atan2(a.y-player.y,a.x-player.x)}else a.alert=Math.max(0,a.alert-dt);
      if(a.stateTime<=0){a.stateTime=rand(2.5,10);if(a.alert<=0){a.state=pick(['graze','wander','rest','wander']);if(a.state==='wander')a.heading=rand(0,Math.PI*2)}}
      let speed=a.state==='flee'?a.speed*2.7:a.state==='wander'?a.speed*.4:a.state==='graze'?a.speed*.08:0;if(a.state==='graze')a.hunger=Math.max(0,a.hunger-dt*.24);if(a.state==='drink'&&a.x>200)a.thirst=Math.max(0,a.thirst-dt*.4);
      if(a.thirst>78&&a.state==='wander'){a.heading=Math.atan2(80-a.y,260-a.x);speed=a.speed*.48;if(Math.hypot(a.x-260,a.y-80)<40)a.state='drink'}
      a.x+=Math.cos(a.heading)*speed*dt;a.y+=Math.sin(a.heading)*speed*dt;
      if(a.kind==='Hyena'||a.kind==='Jackal'||a.kind==='Wild dog'){for(const prey of animals){if(!prey.alive||!['Gazelle','Impala','Warthog'].includes(prey.kind))continue;if(dist(a,prey)<12){prey.health-=dt*10;if(prey.health<=0){prey.alive=false;note(`A ${a.kind.toLowerCase()} has brought down a ${prey.kind.toLowerCase()}.`)}break}}}
      if(a.x>850)a.x=-850;if(a.x< -850)a.x=850;if(a.y>650)a.y=-650;if(a.y< -650)a.y=650;
    }}
  function simulation(dt){if(!player.alive)return;const wasDay=gameDay;world.elapsed=(world.elapsed||0)+dt;timeOfDay=(timeOfDay+dt*24/60)%24;gameDay=1+Math.floor(world.elapsed/60);player.daysAlive+=dt/60;player.ageDays+=dt/60;player.stage=stageFor(player.ageDays);
    if(gameDay!==wasDay){if(gameDay%65===0){season=season==='Dry season'?'Rainy season':'Dry season';note(`The ${season.toLowerCase()} settles over the plains.`)}if(Math.random()<.14)weather=pick(['Clear','Clear','Cloudy','Rain']);if(gameDay%21===0&&player.sex==='Lioness'&&!player.pregnancy)player.heat=3;}
    const n=player.needs;const exertion=(mode==='sprint'&&Object.values(keys).some(Boolean))?1.8:(mode==='run'&&Object.values(keys).some(Boolean))?1.25:.7;n.hunger=clamp(n.hunger-dt*(.018+exertion*.009),0,100);n.thirst=clamp(n.thirst-dt*(.025+(weather==='Hot'?.012:0)),0,100);n.energy=clamp(n.energy+dt*(keys.w||keys.a||keys.s||keys.d?-0.12:timeOfDay>20||timeOfDay<5?.07:.018),0,100);n.stamina=clamp(n.stamina+(keys.w||keys.a||keys.s||keys.d?-dt*(mode==='sprint'?.7:mode==='run'?.3:.1):dt*.2),0,100);n.stress=clamp(n.stress-dt*.08+(n.hunger<20||n.thirst<20?dt*.18:0),0,100);n.temperature=clamp(35+Math.sin((timeOfDay-8)/24*Math.PI*2)*2+(weather==='Hot'?2:0),31,42);
    if(player.injury>0&&n.energy>35&&n.hunger>30&&n.thirst>30){player.injury=Math.max(0,player.injury-dt*.015);n.health=clamp(n.health+dt*.05,0,100)}if(n.hunger<12||n.thirst<12)n.health=clamp(n.health-dt*.08,0,100);if(player.stage==='Elderly')n.health=clamp(n.health-dt*.0015,0,100);
    if(player.heat>0)player.heat=Math.max(0,player.heat-dt/60);if(player.pregnancy){const p=player.pregnancy;p.days+=dt/60;const phase=Math.min(5,Math.floor(p.days/(110/6)));if(phase!==p.phase){p.phase=phase;note(['Early gestation: she seeks quiet cover and rests more.','The pregnancy advances; the pride stays close.','Her abdomen begins to round. She avoids long chases.','Late gestation: a sheltered den is becoming important.','She is close to term. Keep the den quiet and safe.','Labor is near. She has withdrawn to the den.'][phase])}if(p.days>=110)giveBirth()}
    for(const l of pride){if(!l.alive)continue;l.ageDays+=dt/60;l.health=clamp(l.health-dt*(l.ageDays>4500?.0015:0),0,100);if(l.ageDays>5840||l.health<1){l.alive=false;note(`${l.name} has died after a long life with the pride.`);buildPride()}}
    for(const c of player.cubs||[]){if(!c.alive)continue;c.ageDays+=dt/60;c.stage=stageFor(c.ageDays);c.needs=c.needs||{hunger:60,health:100};c.needs.hunger=clamp(c.needs.hunger-dt*.014,0,100);if(c.needs.hunger<18&&player.milk>0&&player.stage!=='Elderly'){c.needs.hunger=clamp(c.needs.hunger+dt*.2,0,100);player.milk=clamp(player.milk-dt*.09,0,100)}if(c.ageDays<60&&c.needs.hunger<10&&player.milk<1){c.needs.health-=dt*.04;if(c.needs.health<1){c.alive=false;note(`${c.name}, a fragile young cub, did not survive.`)}}}
    aiStep(dt);if(n.health<=0){player.alive=false;showDeath()}if(gameDay%3===0&&Math.random()<dt*.001){const dead=animals.find(a=>!a.alive);if(dead&&Math.random()<.25)dead.alive=true}if(Math.floor(world.elapsed/60)!==Math.floor((world.elapsed-dt)/60)){if(gameDay%5===0)reproduceWildlife();updateUI();buildPride();save()}if(actionCooldown>0)actionCooldown-=dt;
  }
  function reproduceWildlife(){const species=['Zebra','Impala','Gazelle','Wildebeest'];for(const kind of species){const alive=animals.filter(a=>a.kind===kind&&a.alive);if(alive.length>2&&Math.random()<.45){const parent=pick(alive);animals.push({...parent,id:Math.random().toString(36).slice(2),x:parent.x+rand(-30,30),y:parent.y+rand(-30,30),speed:parent.speed*.75,size:.55,ageDays:0,health:70,state:'follow',stateTime:8})}}}
  function giveBirth(){const p=player.pregnancy;if(!p)return;player.pregnancy=null;player.lastBirthDay=gameDay;player.offspring+=(p.count||2);player.milk=100;player.x=-390;player.y=-270;player.cubs=[];for(let i=0;i<p.count;i++)player.cubs.push({name:pick(names),ageDays:0,sex:Math.random()<.5?'Male':'Lioness',personality:pick(['Bold','Curious','Gentle','Playful','Cautious']),coat:player.coat,stage:'Newborn',alive:true,needs:{hunger:58,health:100},eyesOpen:false});note(`Labor is over. ${p.count} tiny cub${p.count>1?'s':' is'} breathing in the den; their eyes are closed.`);buildPride();updateUI();showModal('birth')}
  function attemptMate(){if(player.sex!=='Lioness'){toast('Coalition bonds strengthen during patrols and shared hunts.');return}if(player.pregnancy){toast('She is already carrying cubs.');return}if(player.heat<=0){player.heat=3;toast('She enters a brief receptive phase. Stay near her mate and rest together.');return}const mate=pride.find(l=>l.name===player.mate&&l.alive&&l.sex==='Male');if(!mate){toast('No bonded male is close enough to mate.');return}if(dist(player,mate)>185){toast(`${mate.name} is too far away. Call the pride closer.`);return}player.pregnancy={days:0,phase:0,count:Math.floor(rand(1,5)),father:mate.name,conceptionDay:gameDay};player.heat=0;note(`${player.mate} mates with ${player.name}. Gestation begins; birth is not due for about 110 days.`);toast('Conception · six stages of gestation begin.');updateUI()}
  function startHunt(){if(player.stage==='Newborn'||player.stage==='Young cub'){toast('You are too young to hunt. Stay close to the pride.');return}const candidates=animals.filter(a=>a.alive&&['Zebra','Wildebeest','Gazelle','Impala','Buffalo','Warthog'].includes(a.kind)).sort((a,b)=>dist(player,a)-dist(player,b));const target=candidates[0];if(!target||dist(player,target)>245){toast('No prey nearby. Follow tracks toward the herds.');return}huntTarget=target;if(mode!=='stalk'){toast(`${target.kind} herd spotted. Switch to STALK and creep closer.`);return}const d=dist(player,target);if(d>60){player.needs.stamina=clamp(player.needs.stamina-8,0,100);player.needs.stress=clamp(player.needs.stress+3,0,100);toast(`Still ${Math.round(d)}m away. Stay low and close the gap.`);return}target.alert=2;target.state='flee';target.heading=Math.atan2(target.y-player.y,target.x-player.x);player.needs.stamina=clamp(player.needs.stamina-22,0,100);player.needs.energy=clamp(player.needs.energy-8,0,100);const success=player.needs.stamina>16&&Math.random()<clamp(.77-d/180-player.injury*.004+(player.experience*.004),.12,.8);if(success){target.alive=false;player.meat+=Math.round(target.kind==='Buffalo'?42:target.kind==='Zebra'||target.kind==='Wildebeest'?29:15);player.experience++;player.needs.hunger=clamp(player.needs.hunger+28,0,100);note(`A coordinated stalk ends in a kill. The pride shares a ${target.kind.toLowerCase()}.`);toast(`Hunt successful · ${target.kind} meat shared with the pride.`);if(player.pregnancy)player.needs.stress=clamp(player.needs.stress+5,0,100)}else{player.injury=clamp(player.injury+rand(5,16),0,100);player.needs.health=clamp(player.needs.health-10,0,100);player.needs.stress=clamp(player.needs.stress+12,0,100);note(`The ${target.kind.toLowerCase()} escapes. ${player.name} is hurt in the chase.`);toast('The prey escaped · you were injured. Rest and recover.')}huntTarget=null;updateUI()}
  function doAction(a){if(actionCooldown>0)return;actionCooldown=.45;const n=player.needs,near=nearestThing();switch(a){case'hunt':startHunt();break;case'drink':if(Math.hypot(player.x-260,player.y-80)<145){n.thirst=100;n.temperature=clamp(n.temperature-2,31,42);toast('Drank from the Mara River · thirst restored.')}else toast('No water in reach. The river lies east, beyond the reeds.');break;case'rest':n.energy=clamp(n.energy+27,0,100);n.stamina=clamp(n.stamina+36,0,100);n.stress=clamp(n.stress-12,0,100);if(player.injury)player.injury=Math.max(0,player.injury-1);if(player.pregnancy)toast('Resting in the den · pregnancy needs are met.');else toast('You settle in the grass · energy and stamina recover.');break;case'groom':{const buddy=pride.find(x=>x.alive&&dist(player,x)<90);if(buddy){buddy.bond=clamp(buddy.bond+4,0,100);n.stress=clamp(n.stress-8,0,100);toast(`You groom ${buddy.name}. Trust deepens.`)}else{n.stress=clamp(n.stress-4,0,100);toast('You carefully clean your coat and paws.')}break}case'roar':n.stamina=clamp(n.stamina-2,0,100);n.stress=clamp(n.stress-2,0,100);note(`${player.name} roars across the ${player.x>200?'riverbank':'grassland'}. Distant calls answer.`);toast('Your roar carries across the territory.');if(soundOn)tone(150,.35,'sawtooth',.045);for(const a of animals)if(a.kind==='Hyena'&&dist(a,player)<200)a.alert=2;break;case'call':{let count=0;for(const l of pride)if(l.alive&&dist(player,l)>95){l.x=player.x+rand(-50,50);l.y=player.y+rand(-45,45);count++}toast(count?`Your call brings ${count} pride member${count>1?'s':''} closer.`:'The pride is already close.');break}case'interact':if(near?.kind==='water')doAction('drink');else if(near?.animal){toast(`${near.label} · ${near.animal.state==='graze'?'grazing':'moving'} · ${Math.round(dist(player,near.animal))}m away.`)}else if(Math.hypot(player.x+390,player.y+270)<130&&player.cubs?.length){toast('At the den: cubs are warm and sheltered. Press G to groom or C to call.')}else toast('You pause and scent the breeze. The plains stretch in every direction.');break;case'mate':attemptMate();break;case'feed':if(player.meat>0){player.meat--;n.hunger=clamp(n.hunger+27,0,100);player.milk=clamp(player.milk+8,0,100);toast('You feed on a cached kill. Hunger eases.')}else toast('No cached meat. Find a herd and make a kill.');break;case'profile':showModal('profile');break}}
  function tone(f,d,type,v){try{const ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=f;g.gain.value=v;o.connect(g);g.connect(ac.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+d);o.stop(ac.currentTime+d);setTimeout(()=>ac.close(),d*1000+100)}catch(e){}}
  function movement(dt){let dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0);if(!dx&&!dy)return;const len=Math.hypot(dx,dy);dx/=len;dy/=len;let speed=mode==='sprint'?180:mode==='run'?110:mode==='stalk'?36:66;if(player.stage==='Newborn'||player.stage==='Young cub')speed*=.4;if(player.injury>30)speed*=.65;if(player.needs.stamina<8)speed*=.55;player.x=clamp(player.x+dx*speed*dt,-810,810);player.y=clamp(player.y+dy*speed*dt,-620,620);player.heading=Math.atan2(dy,dx);moveAccum+=dt;if(moveAccum>.3){player.needs.stamina=clamp(player.needs.stamina-dt*(mode==='sprint'?.7:mode==='run'?.25:.05),0,100);moveAccum=0}}
  function frame(now){const dt=Math.min(.06,(now-lastFrame)/1000);lastFrame=now;movement(dt);simulation(dt);draw();requestAnimationFrame(frame)}
  function draw(){ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);let dark=timeOfDay<5||timeOfDay>19?1:timeOfDay<7?(7-timeOfDay)/2:timeOfDay>17?(timeOfDay-17)/2:0;sky.addColorStop(0,dark>.7?'#283344':dark>.25?'#7b7160':'#8fa6a0');sky.addColorStop(.38,dark>.7?'#72736a':dark>.25?'#d29c6c':'#d7c58e');sky.addColorStop(1,'#968e58');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
