  function drawHills(){ctx.fillStyle='#777b4d';ctx.beginPath();ctx.moveTo(0,H*.39);for(let x=0;x<=W+40;x+=40)ctx.lineTo(x,H*.31+Math.sin(x*.006+1)*25+Math.sin(x*.013)*13);ctx.lineTo(W,H*.66);ctx.lineTo(0,H*.66);ctx.fill();ctx.fillStyle='rgba(194,170,104,.32)';ctx.beginPath();ctx.moveTo(0,H*.47);for(let x=0;x<=W+40;x+=40)ctx.lineTo(x,H*.4+Math.sin(x*.008+3)*17);ctx.lineTo(W,H*.67);ctx.lineTo(0,H*.67);ctx.fill()}
