  function drawAnimal(a){const p=worldToScreen(a);ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.scale*(a.size||1),p.scale*(a.size||1));if(a.kind==='Vulture'){ctx.fillStyle='#302c25';ctx.beginPath();ctx.ellipse(0,0,8,4,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#302c25';ctx.beginPath();ctx.moveTo(-4,-2);ctx.lineTo(-14,-7);ctx.lineTo(0,-4);ctx.lineTo(14,-7);ctx.lineTo(4,-2);ctx.stroke();ctx.restore();return}if(a.kind==='Crocodile'){ctx.fillStyle='#3c4931';ctx.beginPath();ctx.ellipse(0,0,17,5,0,0,Math.PI*2);ctx.fill();ctx.fillRect(11,-2,9,3);ctx.restore();return}let col=({Zebra:'#e5ddc8',Wildebeest:'#685c43',Gazelle:'#c69b60',Impala:'#bd9b64',Buffalo:'#3e382d',Warthog:'#746046',Elephant:'#777a70',Giraffe:'#d5b672',Hyena:'#857458',Leopard:'#b4945e',Cheetah:'#d3af6b','Wild dog':'#b59d69',Jackal:'#9c8154'})[a.kind]||'#b7a16d';ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(0,-6,a.kind==='Elephant'?20:11,a.kind==='Elephant'?11:6,-.05,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(10,-10,a.kind==='Elephant'?7:5,0,Math.PI*2);ctx.fill();ctx.strokeStyle=col;ctx.lineWidth=2;for(let j of [-7,-2,4,8]){ctx.beginPath();ctx.moveTo(j,-3);ctx.lineTo(j+(a.state==='flee'?-2:0),4);ctx.stroke()}if(a.kind==='Zebra'){ctx.strokeStyle='#453e33';ctx.lineWidth=1;for(let j=-7;j<8;j+=4){ctx.beginPath();ctx.moveTo(j,-11);ctx.lineTo(j+3,-2);ctx.stroke()}}if(a.kind==='Giraffe'){ctx.strokeStyle=col;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(7,-9);ctx.lineTo(11,-22);ctx.stroke();ctx.beginPath();ctx.arc(12,-22,4,0,Math.PI*2);ctx.fill()}if(a.kind==='Elephant'){ctx.strokeStyle=col;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(15,-9);ctx.quadraticCurveTo(22,-6,18,1);ctx.stroke()}if(a.alert>0){ctx.fillStyle='#f6dc9c';ctx.beginPath();ctx.arc(0,-25,2,0,7);ctx.fill()}ctx.restore()}
