-  function showModal(type){const back=$('#modal-backdrop'),body=$('#modal-content');back.classList.add('open');if(type==='profile'){body.innerHTML=`<span class="eyebrow">LION PROFILE · GENERATION ${player.offspring?2:1}</span><h2>${player.name}</h2><p>${player.stage} ${player.sex.toLowerCase()} · ${ageText(player.ageDays)} · ${player.personality}, ${player.temperament.toLowerCase()}. Her family, temperament, and inherited traits persist as the plains change.</p><div class="modal-grid"><div class="modal-card"><b>Appearance</b><span>Golden coat · ${player.eyes} eyes · ${player.scar==='none'?'unscarred':'small facial scar'}<br>Inherited build: ${Math.round(player.genetics.size*100)}%</span></div><div class="modal-card"><b>Family</b><span>Mother ${player.mother||'unknown'} · Father ${player.father||'unknown'}<br>${player.offspring} offspring · mate ${player.mate||'none'}</span></div><div class="modal-card"><b>Current path</b><span>${player.mode} · ${player.meat} cached meat<br>${player.experience} successful hunts</span></div><div class="modal-card"><b>Reproduction</b><span>${player.pregnancy?`${Math.floor(player.pregnancy.days)} / 110 days · ${['early','middle','late','advanced','term','labor'][player.pregnancy.phase]}`:player.heat>0?'In heat · receptive for a short window':'Not pregnant'}<br>Milk ${Math.round(player.milk)}%</span></div></div><button class="primary-button" onclick="window.gameAction('mate')">SEEK MATE / BEGIN REPRODUCTIVE CYCLE</button>`}else if(type==='help'){body.innerHTML=`<span class="eyebrow">FIELD GUIDE</span><h2>Learn to live here.</h2><p>The savanna is running even when you rest. Days pass quickly, herds move, predators hunt, and needs decline. Your life is saved automatically on this device.</p><div class="modal-grid"><div class="modal-card"><b>Hunt</b><span>Set STALK, approach prey, then press F within about 60m. A failed chase can injure you.</span></div><div class="modal-card"><b>Survive</b><span>Drink at the river east of Acacia Rise. Rest to regain energy. Eat cached meat with E or the nearby interaction.</span></div><div class="modal-card"><b>Motherhood</b><span>Lionesses cycle into heat; find a bonded male to conceive. Gestation lasts 110 in-game days (~110 real minutes). Return to the den for birth.</span></div><div class="modal-card"><b>Controls</b><span>WASD move · Shift run · F hunt · E drink/eat · Z rest · G groom · R roar · C call pride · Space interact · P profile.</span></div></div><p>Newborn cubs are blind, dependent, and grow over in-game months. Keep them sheltered, groom them, and protect the pride.</p>`}else if(type==='family'){body.innerHTML=`<span class="eyebrow">GENERATIONS</span><h2>The family tree</h2><p>Bloodlines carry coat, build, and mane traits forward. A descendant can inherit the story of this life.</p><div class="family-row"><div class="family-node">${player.mother||'Sanaa'}<small>Mother</small></div><span class="family-connector">→</span><div class="family-node">${player.name}<small>${player.stage}</small></div><span class="family-connector">→</span><div class="family-node">${player.cubs?.length?player.cubs.map(c=>c.name).join(', '):'Future cubs'}<small>Offspring</small></div></div><p>Offspring: ${player.offspring} · known parents: ${player.mother||'unknown'} and ${player.father||'unknown'} · survival history follows each lion.</p><button class="primary-button" onclick="window.gameAction('profile')">VIEW LION RECORD</button>`}else if(type==='birth'){body.innerHTML=`<span class="eyebrow">A NEW GENERATION</span><h2>Life begins in the den.</h2><p>${player.name} has given birth to ${player.cubs.length} cub${player.cubs.length===1?'':'s'}. Their eyes are closed and they cannot follow or feed themselves. They need warmth, nursing, grooming, and a quiet shelter.</p><div class="modal-grid">${player.cubs.map(c=>`<div class="modal-card"><b>${c.name} · ${c.sex}</b><span>Newborn · ${c.personality}<br>Eyes closed · fully dependent</span></div>`).join('')}</div><button class="primary-button" onclick="document.querySelector('#modal-backdrop').classList.remove('open')">RETURN TO THE DEN</button>`}else if(type==='death'){body.innerHTML=`<span class="eyebrow">THE END OF A LIFE · DAY ${gameDay}</span><h2>${player.name}'s story continues.</h2><p>${player.name} has died. The pride and ecosystem remain. ${player.offspring?`Her descendants, ${player.cubs?.filter(c=>c.alive).map(c=>c.name).join(', ')||'and their future offspring'}, carry her line.`:'Her family story is recorded in the pride.'}</p><div class="modal-grid"><div class="modal-card"><b>Life lived</b><span>${ageText(player.ageDays)} · ${player.experience} successful hunts</span></div><div class="modal-card"><b>Legacy</b><span>${player.offspring} offspring · ${pride.filter(a=>a.alive).length} pride members remain</span></div></div><button class="primary-button" onclick="window.gameAction('descendant')">CONTINUE AS A DESCENDANT</button>`}else if(type==='world'){body.innerHTML=`<span class="eyebrow">MARA TERRITORY</span><h2>The living plains.</h2><p>Season: ${season} · weather: ${weather}. Water lies east. The rocky den is northwest. Territory disputes, grazing herds, and predator movements unfold whether or not you are nearby.</p><div class="modal-grid"><div class="modal-card"><b>Grasslands</b><span>Zebra, wildebeest, gazelles, impala, buffalo and warthogs migrate between forage and water.</span></div><div class="modal-card"><b>Predators</b><span>Hyena clans, leopards, cheetahs, wild dogs and jackals hunt independently. Vultures follow kills.</span></div><div class="modal-card"><b>River & marsh</b><span>Elephants, giraffes and crocodiles share the river corridor. Drink carefully.</span></div><div class="modal-card"><b>Weather</b><span>Rain and dry seasons shift every 65 in-game days. Dawn, heat, dusk and night cycle continuously.</span></div></div>`}else {body.innerHTML=`<span class="eyebrow">LIFE SIMULATION</span><h2>Choose your path.</h2><p>Your choices shape a full lion life, not a series of disconnected scenes.</p><div class="modal-grid">${['Life Simulation','Pride Leader','Lioness','Male Lion','Cub Survival','Free Roam','Generational'].map(x=>`<button class="modal-card mode-choice" data-path="${x}"><b>${x}</b><span>${({ 'Life Simulation':'Live a complete life in the Mara Pride.','Pride Leader':'Build bonds, lead hunts and defend territory.','Lioness':'Pregnancy, denning, nursing and raising cubs.','Male Lion':'Coalition bonds, dispersal and territory challenges.','Cub Survival':'Begin as a dependent newborn cub.','Free Roam':'Explore without pride obligations.','Generational':'Continue the family line through descendants.'})[x]}</span></button>`).join('')}</div><div class="modal-grid"><label class="modal-card">Name <input id="custom-name" value="${player.name}" maxlength="16"></label><label class="modal-card">Sex <select id="custom-sex"><option ${player.sex==='Lioness'?'selected':''}>Lioness</option><option ${player.sex==='Male'?'selected':''}>Male</option></select></label><label class="modal-card">Coat <input id="custom-coat" type="color" value="${player.coat}"></label><label class="modal-card">Eyes <select id="custom-eyes"><option>Amber</option><option>Gold</option><option>Hazel</option><option>Brown</option></select></label><label class="modal-card">Mane <input id="custom-mane" type="color" value="${player.mane}"></label><label class="modal-card">Scar <select id="custom-scar"><option value="none">None</option><option value="facial">Facial scar</option><option value="ear">Torn ear</option></select></label></div><button class="primary-button" id="apply-custom">BEGIN / APPLY LION</button>`;setTimeout(()=>{$$('.mode-choice').forEach(b=>b.onclick=()=>{player.mode=b.dataset.path;if(b.dataset.path==='Cub Survival'){player.ageDays=0;player.stage='Newborn';player.sex='Lioness';player.needs.hunger=55;player.needs.thirst=70;player.mother='Sanaa'}if(b.dataset.path==='Male Lion'){player.sex='Male';player.mate='';player.pregnancy=null}if(b.dataset.path==='Lioness')player.sex='Lioness';if(b.dataset.path==='Free Roam')player.mode='Free Roam';if(b.dataset.path==='Generational'&&player.cubs?.length){const c=player.cubs.find(z=>z.alive&&z.ageDays>14);if(c){player.name=c.name;player.sex=c.sex;player.ageDays=c.ageDays;player.coat=c.coat;player.personality=c.personality;player.cubs=[];player.offspring=0;player.mode='Generational'}}updateUI();buildPride();toast(`${player.mode} path selected.`);save()});$('#apply-custom').onclick=()=>{player.name=$('#custom-name').value.trim()||player.name;player.sex=$('#custom-sex').value;player.coat=$('#custom-coat').value;player.mane=$('#custom-mane').value;player.eyes=$('#custom-eyes').value;player.scar=$('#custom-scar').value;updateUI();buildPride();save();toast('Lion appearance updated.')}} ,0)} }
